12: use std::io::{self, Write};
13: 
14: use camera::Camera;
15: use hittable::{Hittable, HittableList};
16: use ray::Ray;
17: use sphere::Sphere;
18: use vec3::{Colour, Vec3};
19: 
20: const WIDTH: usize = 200;
21: const HEIGHT: usize = 100;
22: 
23: /// The colour seen along a ray: the surface normal where it hits, the sky gradient otherwise.
24: fn ray_colour(ray: &Ray, world: &dyn Hittable) -> Colour {
25:     if let Some(hit) = world.hit(ray, 0.001, f64::INFINITY) {
26:         return (hit.normal + Vec3::new(1.0, 1.0, 1.0)) * 0.5;
27:     }
28:     let t = 0.5 * (ray.direction.unit().y + 1.0);
29:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
30: }
31: 
32: fn scene() -> HittableList {
33:     let mut world = HittableList::default();
34:     world.add(Box::new(Sphere::new(Vec3::new(0.0, 0.0, -1.0), 0.5)));
35:     world.add(Box::new(Sphere::new(Vec3::new(0.0, -100.5, -1.0), 100.0)));
36:     world
37: }
38: 
39: /// Every pixel's colour, row by row from the top.
40: fn render(width: usize, height: usize) -> Vec<Colour> {
41:     let world = scene();
42:     let camera = Camera::new(width as f64 / height as f64);
43:     let mut pixels = Vec::with_capacity(width * height);
44:     for row in (0..height).rev() {
45:         for column in 0..width {
46:             let u = column as f64 / (width - 1) as f64;
47:             let v = row as f64 / (height - 1) as f64;
48:             pixels.push(ray_colour(&camera.ray(u, v), &world));
49:         }
50:     }
51:     pixels
52: }
53: 
54: fn to_byte(channel: f64) -> u8 {
55:     (255.999 * channel.clamp(0.0, 1.0)) as u8
56: }
57: 
58: fn write_ppm(
59:     out: &mut impl Write,
60:     width: usize,
61:     height: usize,
62:     pixels: &[Colour],
63: ) -> io::Result<()> {
64:     writeln!(out, "P3\n{width} {height}\n255")?;
65:     for pixel in pixels {
66:         writeln!(
67:             out,
68:             "{} {} {}",
69:             to_byte(pixel.x),
70:             to_byte(pixel.y),
71:             to_byte(pixel.z)
72:         )?;
73:     }
74:     Ok(())
75: }
76: 
77: fn main() -> io::Result<()> {
78:     let pixels = render(WIDTH, HEIGHT);
79:     write_ppm(&mut io::stdout().lock(), WIDTH, HEIGHT, &pixels)
80: }
