54: 3. `src/main.rs` - above `fn main`, add the command-line types and parser:
55:    ```rust
56:    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
57:    enum Format {
58:        Png,
59:        Ppm,
60:    }
61: 
62:    #[derive(Debug, PartialEq)]
63:    struct Config {
64:        width: usize,
65:        height: usize,
66:        samples: usize,
67:        output: String,
68:        format: Format,
69:    }
70: 
71:    impl Default for Config {
72:        fn default() -> Self {
73:            Config {
74:                width: WIDTH,
75:                height: HEIGHT,
76:                samples: DEFAULT_SAMPLES,
77:                output: DEFAULT_OUTPUT.to_string(),
78:                format: Format::Png,
79:            }
80:        }
81:    }
82: 
83:    impl Config {
84:        fn parse(args: impl Iterator<Item = String>) -> Result<Config, String> {
85:            let mut config = Config::default();
86:            let mut explicit_format: Option<Format> = None;
87:            let mut args = args;
88:            while let Some(arg) = args.next() {
89:                match arg.as_str() {
90:                    "--width" => config.width = parse_number(args.next(), "--width")?,
91:                    "--height" => config.height = parse_number(args.next(), "--height")?,
92:                    "--samples" => config.samples = parse_number(args.next(), "--samples")?,
93:                    "--output" => config.output = parse_value(args.next(), "--output")?,
94:                    "--format" => {
95:                        explicit_format = Some(match args.next().as_deref() {
96:                            Some("png") => Format::Png,
97:                            Some("ppm") => Format::Ppm,
98:                            _ => return Err("--format takes png or ppm".to_string()),
99:                        });
100:                    }
101:                    other => return Err(format!("unknown option: {other}")),
102:                }
103:            }
104:            if config.width < 2 {
105:                return Err("--width must be at least 2".to_string());
106:            }
107:            if config.height < 2 {
108:                return Err("--height must be at least 2".to_string());
109:            }
110:            if config.samples < 1 {
111:                return Err("--samples must be at least 1".to_string());
112:            }
113:            config.format = match explicit_format {
114:                Some(format) => format,
115:                None => match Path::new(&config.output).extension().and_then(|e| e.to_str()) {
116:                    Some("png") => Format::Png,
117:                    Some("ppm") => Format::Ppm,
118:                    _ => return Err("--output must end in .png or .ppm".to_string()),
119:                },
120:            };
121:            Ok(config)
122:        }
123:    }
