125:    fn parse_value(value: Option<String>, option: &str) -> Result<String, String> {
126:        value.ok_or_else(|| format!("{option} needs a value"))
127:    }
128: 
129:    fn parse_number(value: Option<String>, option: &str) -> Result<usize, String> {
130:        parse_value(value, option)?
131:            .parse()
132:            .map_err(|_| format!("{option} needs a number"))
133:    }
